"""Unit + live-benchmark tests for Spike W-030 (#1210) by @planners1490 — `python3 -m unittest discover -s spikes/w030-word-atomicity-floor/tests -p "test_*.py" -v` (one Go toolchain on PATH runs F2 live)."""
import json, pathlib, subprocess, sys, unittest; sys.path.insert(0, str(pathlib.Path(__file__).resolve().parents[1])); import word_atomicity_floor as waf
class TestWordAtomicityFloor(unittest.TestCase):
    def test_classifier_single_vs_multi_word_and_crossings(self): S = waf.parse_structs(waf.TORN_HY + "\n" + waf.CONFUSE_HY + "\nstruct node { next *node\n count int }\ntype buf = []byte\nstruct holder { b buf }"); [self.assertEqual(waf.classify_type(t), waf.TypeLayout(t, 1, "SINGLE_WORD"), t) for t in ("int", "int64", "uint64", "uintptr", "bool", "chan int", "<-chan string", "sync.mutex")]; self.assertEqual([(waf.classify_type(t).kind, waf.classify_type(t).words) for t in ("string", "any", "[]int")], [("MULTI_WORD_HEADER", 2), ("MULTI_WORD_HEADER", 2), ("MULTI_WORD_HEADER", 3)]); self.assertEqual([waf.classify_type(t, S).kind for t in ("*cell", "*plain", "*node")], ["MULTI_WORD_STRUCT", "SINGLE_WORD", "SINGLE_WORD"]); self.assertEqual(waf.classify_type("*holder", S).multiword_fields, (("b", "buf"),)); c = waf.analyze_source('fn w(m map[string]int) { m["k"] = 1 }\nfn main() {\n    managed("map share", "other", "T-MAP") {\n        var m map[string]int\n        task w(m)\n    }\n}'); self.assertEqual((len(c), c[0].is_map_residual, c[0].requires_boxing), (1, True, False))
    def test_reproducers_lower_to_atomic_pointer(self): [self.assertEqual((n, field in go, ".Store(&" in go, ".Load()" in go), (4, True, True, True), name) for name, src, field in (("torn.hy", waf.TORN_HY, "s atomic.Pointer[[]int]"), ("torn_write.hy", waf.TORN_WRITE_HY, "s atomic.Pointer[[]int]"), ("confuse.hy", waf.CONFUSE_HY, "v atomic.Pointer[any]")) for go, n in [waf.lower_to_word_atomic_go(src)]]; self.assertEqual(waf.lower_to_word_atomic_go("fn main() {}"), ("fn main() {}", 0))
    def test_falsifiers_f0_f4_live_and_zero_corpus_regression(self): rep = waf.audit_repository(run_live_go=True); f = rep["falsifiers"]; self.assertTrue(f["F0_unlowered_tearing"]["reproduced"] and f["F1_lowered_word_atomic_floor"]["verified_tear_free"] and f["F2_microbenchmark_budget"]["passes_budget"] and rep["F3_shipped_corpus_zero_cost"]["zero_regression"] and all(rep["F4_spec_guarantees_audit"].values()), rep); self.assertEqual((rep["F3_shipped_corpus_zero_cost"]["shipped_emitted_lines_changed"], waf.main(["--check"])), (0, 0)); out = subprocess.run([sys.executable, waf.__file__, "--check", "--json", "--live-go"], capture_output=True, text=True); self.assertEqual((out.returncode, json.loads(out.stdout)["falsifiers"]["F2_microbenchmark_budget"]["passes_budget"]), (0, True), out.stderr)
